type StorageArea = "local" | "sync";

function area(target: StorageArea): chrome.storage.StorageArea {
  return target === "sync" ? chrome.storage.sync : chrome.storage.local;
}

export async function storageGet<T>(
  key: string,
  target: StorageArea = "local"
): Promise<T | undefined> {
  const result = await area(target).get(key);
  return result[key] as T | undefined;
}

export async function storageSet<T>(
  key: string,
  value: T,
  target: StorageArea = "local"
): Promise<void> {
  await area(target).set({ [key]: value });
}

export async function storageRemove(
  key: string,
  target: StorageArea = "local"
): Promise<void> {
  await area(target).remove(key);
}

export function watchStorageKey<T>(
  key: string,
  onChange: (value: T | undefined) => void,
  target: StorageArea = "local"
): () => void {
  const listener = (
    changes: Record<string, chrome.storage.StorageChange>,
    areaName: string
  ) => {
    if (areaName !== target) return;
    if (!(key in changes)) return;
    onChange(changes[key]?.newValue as T | undefined);
  };
  chrome.storage.onChanged.addListener(listener);
  return () => chrome.storage.onChanged.removeListener(listener);
}

/**
 * Debounces writes to a single storage key so rapid updates (e.g. keystrokes
 * in the editor) collapse into one write instead of hammering the storage API.
 */
export function createDebouncedStorageWriter<T>(
  key: string,
  delayMs: number,
  target: StorageArea = "local"
) {
  let timer: ReturnType<typeof setTimeout> | undefined;
  let pending: T | undefined;

  function write(value: T) {
    pending = value;
    if (timer) clearTimeout(timer);
    timer = setTimeout(() => {
      if (pending !== undefined) void storageSet(key, pending, target);
      timer = undefined;
    }, delayMs);
  }

  function flush() {
    if (timer) clearTimeout(timer);
    timer = undefined;
    if (pending !== undefined) void storageSet(key, pending, target);
  }

  return { write, flush };
}
